/**

# 拷贝配置模板

@see https://kdz8swqlnv.feishu.cn/wiki/EmWAwRjrCiGuuckPghscHU73nze?from=from_copylink

配置模板的命名规则为: {name}.config.lua, 保存在模块清单文件夹 .manifest中.

配置模板的格式为:
```
-- 配置模板
export type _ = {
    -- 类型定义
}

local module:_ = {}

return module
```

注意模板内部 1,6 两行的 _ 符号, 该符号将被自动替换成 Config{name} , 以作为该配置的类型定义. 

本工具会确保能够从模板中找到以下字符串, 否则会抛出错误:
- `export type _ = {`
- `local module:_ = {}`


本工具会执行以下工作:
1. 获取所有组件的配置模板清单.
2. 确保所有的配置名称不重复.
3. 检查指定目录是否存在同名配置 或者 {nameConfig}.ignore, 如果否, 则将它们复制到指定目录, 并修改其内部的 _ 符号.
4. 在 RobloxLsp 扩展库内部创建配置定义文件, 写入配置定义.

本工具的参数有4个:
1. 系统根目录
2. 输出配置文件的目录位置



本工具仅负责拷贝, 不会监听文件变化
 */

const fs = require('fs-extra');
const path = require('path');

function copyConfigTemplate(rootDir, outputDir, outputDefinePath, configParent) {
    // 1. 获取所有组件的配置模板清单
    const templates = getConfigTemplates(rootDir);

    if (templates.length == 0) {
        return
    }

    // 2. 确保所有的配置名称不重复
    ensureUniqueConfigNames(templates);

    // 3. 将模板复制到指定目录并修改 _ 符号
    copyAndModifyTemplates(templates, outputDir);

}

function getConfigTemplates(rootDir) {
    const templates = [];
    const manifestDirs = findManifestDirs(rootDir);

    manifestDirs.forEach(dir => {
        const files = fs.readdirSync(dir);
        files.forEach(file => {
            if (file.endsWith('.config.lua')) {
                templates.push({
                    name: path.basename(file, '.config.lua'),
                    path: path.join(dir, file)
                });
            }
        });
    });

    return templates;
}

function findManifestDirs(dir) {
    const results = [];
    const items = fs.readdirSync(dir, { withFileTypes: true });

    for (const item of items) {
        if (item.isDirectory()) {
            if (item.name === '.manifest') {
                results.push(path.join(dir, item.name));
            } else {
                results.push(...findManifestDirs(path.join(dir, item.name)));
            }
        }
    }

    return results;
}

function ensureUniqueConfigNames(templates) {
    const names = templates.map(t => t.name);
    const duplicates = names.filter((name, index) => names.indexOf(name) !== index);
    if (duplicates.length > 0) {
        throw new Error(`发现重复的配置名称: ${duplicates.join(', ')}`);
    }
}

function copyAndModifyTemplates(templates, outputDir) {
    templates.forEach(template => {

        // if file exists, then ignore
        const outputPath = path.join(outputDir, `${template.name}Config.lua`);

        const ignorePath = path.join(outputDir, `${template.name}Config.ignore`);
        if (fs.existsSync(outputPath) || fs.existsSync(ignorePath)) {
            console.log(`Config file ${outputPath} already exists. Skipping.`);
            return;
        }

        const content = fs.readFileSync(template.path, 'utf8');


        if (!content.includes('export type _ = {')) {
            throw new Error(`Template ${template.name} is missing required string 'export type _ = {'`);
        }
        if (!content.includes('local module: _ = {')) {
            throw new Error(`Template ${template.name} is missing required string 'local module: _ = {'`);
        }

        var modifiedContent = ""

        // Add template path as a comment at the beginning of the content
        modifiedContent = `-- Template path: ${template.path}\n\n`;

        modifiedContent += content.replace(/export type _ = {/, `export type ${template.name}Config = {`)
            .replace(/local module: _ = {/, `local module:${template.name}Config = {`);

        fs.ensureDirSync(outputDir)
        fs.writeFileSync(outputPath, modifiedContent);
    });
}

function createConfigDefinitionFile(templates, outputDefinePath, configParent) {
    let definitionContent = '-- 自动生成的配置定义文件\n\n';
    templates.forEach(template => {

        definitionContent += `export type ${template.name}Config = typeof(require(${configParent}.${template.name}Config))\n\n`

    })
    fs.writeFileSync(outputDefinePath, definitionContent);
}

// 获取命令行参数
var [rootDir, outputConfigsDir] = process.argv.slice(2);
// [rootDir, outputConfigsDir] = ["src/Systems", "src/Configs/SystemConfigs"]

// 执行主函数
copyConfigTemplate(rootDir, outputConfigsDir);
